1	import { canonicalize, sha256 } from './canonicalize.ts';
2	
3	export const UNRESOLVED_REASONS = [
4		'unparsed-file',
5		'unsupported-language',
6		'unsupported-syntax',
7		'unresolved-specifier',
8		'external-module-boundary',
9		'builtin-module-boundary',
10		'linked-set-boundary',
11		'unresolved-symbol',
12		'ambiguous-definition',
13		'dynamic-member-access',
14		'computed-property-key',
15		'string-keyed-lookup',
16		'property-alias-write-uncertain',
17		'higher-order-call-boundary',
18		'stale-snapshot',
19	] as const;
20	
21	export type UnresolvedReason = (typeof UNRESOLVED_REASONS)[number];
22	
23	export interface SymbolAnchor {
24		readonly schema: 'guessless.symbol-anchor/v1';
25		readonly file: string;
26		readonly semanticPath: readonly string[];
27		readonly fingerprint: string;
28	}
29	
30	export interface UnresolvedSite {
31		readonly site: SymbolAnchor;
32		readonly reason: UnresolvedReason;
33		readonly detail: string;
34	}
35	
36	export const SAFE_CHANGE_ROLES = [
37		'declaration',
38		'reference',
39		'read',
40		'write',
41		'read-write',
42		'call',
43		'import',
44		'export',
45		'alias',
46		'namespace',
47		'barrel',
48		'witness',
49	] as const;
50	
51	export type SafeChangeRole = (typeof SAFE_CHANGE_ROLES)[number];
52	export type SafeChangeIntent = 'rename' | 'delete' | 'entry-point';
53	export interface SafeChangeBindingSelector {
54		readonly file: string;
55		readonly name: string;
56		readonly space: 'value' | 'type' | 'namespace' | 'typeof' | 'any';
57		readonly from?: SymbolAnchor;
58	}
59	export type SafeChangeTarget = SymbolAnchor | SafeChangeBindingSelector;
60	
61	export interface SafeChangeImpactResult {
62		readonly site: SymbolAnchor;
63		readonly roles: readonly SafeChangeRole[];
64		readonly witness: readonly SymbolAnchor[];
65	}
66	
67	export type QueryRequest =
68		| { readonly kind: 'addFile'; readonly file: string }
69		| {
70				readonly kind:
71					| 'definitionOf'
72					| 'referencesOf'
73					| 'readsOf'
74					| 'writesOf'
75					| 'capturesOf'
76					| 'reachableFrom'
77					| 'reaches';
78				readonly target: SymbolAnchor;
79		  }
80		| { readonly kind: 'exportedNames'; readonly file: string }
81		| {
82				readonly kind: 'resolveBinding';
83				readonly file: string;
84				readonly name: string;
85				readonly space: 'value' | 'type' | 'namespace' | 'typeof' | 'any';
86				readonly scope: SymbolAnchor | null;
87		  }
88		| {
89				readonly kind: 'safeChangeImpact';
90				readonly snapshot: string;
91				readonly intent: SafeChangeIntent;
92				readonly target: SafeChangeTarget;
93		  };
94	
95	interface ReceiptBase<T> {
96		readonly schema: 'guessless.receipt/v1';
97		readonly query: string;
98		readonly request: QueryRequest;
99		readonly snapshot: string;
100		readonly results: readonly T[];
101		readonly integrity: string;
102	}
103	
104	export interface CompleteReceipt<T> extends ReceiptBase<T> {
105		readonly state: 'complete';
106	}
107	export interface PartialReceipt<T> extends ReceiptBase<T> {
108		readonly state: 'partial';
109		readonly unresolved: readonly UnresolvedSite[];
110	}
111	export interface RefusedReceipt<T> extends ReceiptBase<T> {
112		readonly state: 'refused';
113		readonly reason: UnresolvedReason;
114		readonly detail: string;
115	}
116	export type Receipt<T> = CompleteReceipt<T> | PartialReceipt<T> | RefusedReceipt<T>;
117	type WithoutIntegrity<T> = T extends unknown ? Omit<T, 'integrity'> : never;
118	type UnsignedReceipt<T> = WithoutIntegrity<Receipt<T>>;
119	
120	const baseKeys = ['query', 'request', 'results', 'schema', 'snapshot', 'state'] as const;
121	const anchorKeys = ['file', 'fingerprint', 'schema', 'semanticPath'] as const;
122	
123	export function makeReceipt<T>(receipt: UnsignedReceipt<T>): Receipt<T> {
124		assertReceiptShape(receipt);
125		return { ...receipt, integrity: sha256(receipt) } as Receipt<T>;
126	}
127	
128	export function verifyReceipt(value: unknown, currentSnapshot?: string): value is Receipt<unknown> {
129		try {
130			assertReceiptShape(value);
131			const record = value as Record<string, unknown>;
132			if (typeof record.integrity !== 'string' || !/^[a-f0-9]{64}$/.test(record.integrity))
133				return false;
134			if (currentSnapshot !== undefined && record.snapshot !== currentSnapshot) return false;
135			const { integrity, ...unsigned } = record;
136			return integrity === sha256(unsigned);
137		} catch {
138			return false;
139		}
140	}
141	
142	function exactKeys(record: Record<string, unknown>, extras: readonly string[]): void {
143		const expected = [
144			...baseKeys,
145			...extras,
146			...('integrity' in record ? ['integrity'] : []),
147		].sort();
148		const actual = Object.keys(record).sort();
149		if (actual.join('\u0000') !== expected.join('\u0000'))
150			throw new TypeError('receipt state has invalid or cross-state fields');
151	}
152	
153	function assertReceiptShape(value: unknown): void {
154		if (!isRecord(value) || Array.isArray(value))
155			throw new TypeError('receipt must be an object, never a bare list');
156		const record = value;
157		if (
158			record.schema !== 'guessless.receipt/v1' ||
159			typeof record.query !== 'string' ||
160			!Array.isArray(record.results) ||
161			typeof record.snapshot !== 'string' ||
162			!/^[a-f0-9]{64}$/.test(record.snapshot)
163		)
164			throw new TypeError('invalid receipt envelope');
165		assertRequest(record.query, record.request);
166		if (record.state === 'complete') exactKeys(record, []);
167		else if (record.state === 'partial') {
168			exactKeys(record, ['unresolved']);
169			if (!Array.isArray(record.unresolved) || record.unresolved.length === 0)
170				throw new TypeError('partial receipt needs unresolved sites');
171			for (const item of record.unresolved) assertUnresolved(item);
172		} else if (record.state === 'refused') {
173			exactKeys(record, ['detail', 'reason']);
174			if (
175				record.results.length !== 0 ||
176				!isReason(record.reason) ||
177				typeof record.detail !== 'string'
178			)
179				throw new TypeError('invalid refused receipt');
180		} else throw new TypeError('receipt state must be complete, partial, or refused');
181		assertQueryResults(record.query, record.results);
182	}
183	
184	function assertRequest(query: string, value: unknown): asserts value is QueryRequest {
185		if (!isRecord(value) || value.kind !== query)
186			throw new TypeError('receipt request must match query');
187		if (query === 'addFile' || query === 'exportedNames') {
188			if (!hasExactKeys(value, ['file', 'kind']) || typeof value.file !== 'string')
189				throw new TypeError(`invalid ${query} request`);
190			return;
191		}
192		if (
193			[
194				'definitionOf',
195				'referencesOf',
196				'readsOf',
197				'writesOf',
198				'capturesOf',
199				'reachableFrom',
200				'reaches',
201			].includes(query)
202		) {
203			if (!hasExactKeys(value, ['kind', 'target']) || !isAnchor(value.target))
204				throw new TypeError(`invalid ${query} request`);
205			return;
206		}
207		if (query === 'resolveBinding') {
208			if (
209				!hasExactKeys(value, ['file', 'kind', 'name', 'scope', 'space']) ||
210				typeof value.file !== 'string' ||
211				typeof value.name !== 'string' ||
212				!['value', 'type', 'namespace', 'typeof', 'any'].includes(String(value.space)) ||
213				(value.scope !== null && !isAnchor(value.scope))
214			)
215				throw new TypeError('invalid resolveBinding request');
216			return;
217		}
218		if (query === 'safeChangeImpact') {
219			if (
220				!hasExactKeys(value, ['intent', 'kind', 'snapshot', 'target']) ||
221				typeof value.snapshot !== 'string' ||
222				!/^[a-f0-9]{64}$/.test(value.snapshot) ||
223				!['rename', 'delete', 'entry-point'].includes(String(value.intent)) ||
224				(!isAnchor(value.target) && !isSafeChangeBindingSelector(value.target))
225			)
226				throw new TypeError('invalid safeChangeImpact request');
227			return;
228		}
229		throw new TypeError(`unknown receipt query '${query}'`);
230	}
231	
232	function assertQueryResults(query: string, results: unknown[]): void {
233		if (query === 'addFile') {
234			if (results.length !== 0) throw new TypeError('addFile refusal cannot have results');
235			return;
236		}
237		if (query === 'definitionOf' || query === 'resolveBinding') {
238			if (results.length > 1 || !results.every(isAnchor))
239				throw new TypeError(`${query} requires at most one anchor result`);
240			return;
241		}
242		if (query === 'referencesOf' || query === 'readsOf' || query === 'writesOf') {
243			for (const result of results) {
244				if (
245					!isRecord(result) ||
246					!hasExactKeys(result, ['access', 'site']) ||
247					!isAnchor(result.site) ||
248					!['read', 'write', 'read-write'].includes(String(result.access))
249				)
250					throw new TypeError('invalid reference result');
251				if (query === 'readsOf' && result.access === 'write')
252					throw new TypeError('readsOf contains a write-only result');
253				if (query === 'writesOf' && result.access === 'read')
254					throw new TypeError('writesOf contains a read-only result');
255			}
256			return;
257		}
258		if (query === 'exportedNames') {
259			for (const result of results)
260				if (
261					!isRecord(result) ||
262					!hasExactKeys(result, ['module', 'name']) ||
263					!isAnchor(result.module) ||
264					typeof result.name !== 'string'
265				)
266					throw new TypeError('invalid export result');
267			return;
268		}
269		if (query === 'capturesOf') {
270			for (const result of results)
271				if (
272					!isRecord(result) ||
273					!hasExactKeys(result, ['isWritten', 'references', 'symbol']) ||
274					!isAnchor(result.symbol) ||
275					!Array.isArray(result.references) ||
276					!result.references.every(isAnchor) ||
277					typeof result.isWritten !== 'boolean'
278				)
279					throw new TypeError('invalid capture result');
280			return;
281		}
282		if (query === 'reachableFrom' || query === 'reaches') {
283			const symbols = new Set<string>();
284			for (const result of results) {
285				if (
286					!isRecord(result) ||
287					!hasExactKeys(result, ['symbol', 'witness']) ||
288					!isAnchor(result.symbol) ||
289					!Array.isArray(result.witness) ||
290					result.witness.length === 0 ||
291					!result.witness.every(isAnchor)
292				)
293					throw new TypeError('invalid reachability result');
294				const identity = canonicalize(result.symbol);
295				if (symbols.has(identity)) throw new TypeError('duplicate reachability result');
296				symbols.add(identity);
297			}
298			return;
299		}
300		if (query === 'safeChangeImpact') {
301			const sites = new Set<string>();
302			for (const result of results) {
303				if (
304					!isRecord(result) ||
305					!hasExactKeys(result, ['roles', 'site', 'witness']) ||
306					!isAnchor(result.site) ||
307					!Array.isArray(result.roles) ||
308					result.roles.length === 0 ||
309					!result.roles.every(isSafeChangeRole) ||
310					new Set(result.roles).size !== result.roles.length ||
311					!Array.isArray(result.witness) ||
312					!result.witness.every(isAnchor)
313				)
314					throw new TypeError('invalid safe-change impact result');
315				const identity = canonicalize(result.site);
316				if (sites.has(identity)) throw new TypeError('duplicate safe-change impact site');
317				sites.add(identity);
318			}
319			return;
320		}
321		throw new TypeError(`unknown receipt query '${query}'`);
322	}
323	
324	function assertUnresolved(value: unknown): void {
325		if (
326			!isRecord(value) ||
327			!hasExactKeys(value, ['detail', 'reason', 'site']) ||
328			!isAnchor(value.site) ||
329			!isReason(value.reason) ||
330			typeof value.detail !== 'string'
331		)
332			throw new TypeError('invalid unresolved site');
333	}
334	function isReason(value: unknown): value is UnresolvedReason {
335		return typeof value === 'string' && (UNRESOLVED_REASONS as readonly string[]).includes(value);
336	}
337	function isSafeChangeRole(value: unknown): value is SafeChangeRole {
338		return typeof value === 'string' && (SAFE_CHANGE_ROLES as readonly string[]).includes(value);
339	}
340	function isSafeChangeBindingSelector(value: unknown): value is SafeChangeBindingSelector {
341		if (!isRecord(value)) return false;
342		const keys =
343			value.from === undefined ? ['file', 'name', 'space'] : ['file', 'from', 'name', 'space'];
344		return (
345			hasExactKeys(value, keys) &&
346			typeof value.file === 'string' &&
347			typeof value.name === 'string' &&
348			['value', 'type', 'namespace', 'typeof', 'any'].includes(String(value.space)) &&
349			(value.from === undefined || isAnchor(value.from))
350		);
351	}
352	function isRecord(value: unknown): value is Record<string, unknown> {
353		return value !== null && typeof value === 'object' && !Array.isArray(value);
354	}
355	function hasExactKeys(record: Record<string, unknown>, keys: readonly string[]): boolean {
356		return Object.keys(record).sort().join('\u0000') === [...keys].sort().join('\u0000');
357	}
358	
359	export function isAnchor(value: unknown): value is SymbolAnchor {
360		if (!isRecord(value) || !hasExactKeys(value, anchorKeys)) return false;
361		return (
362			value.schema === 'guessless.symbol-anchor/v1' &&
363			typeof value.file === 'string' &&
364			Array.isArray(value.semanticPath) &&
365			value.semanticPath.length > 0 &&
366			value.semanticPath.every((part) => typeof part === 'string') &&
367			typeof value.fingerprint === 'string' &&
368			/^[a-f0-9]{64}$/.test(value.fingerprint)
369		);
370	}
371	
372	export function receiptCanonicalForm(receipt: Receipt<unknown>): string {
373		return canonicalize(receipt);
374	}
