1	import { builtinModules } from 'node:module';
2	import type { Analyzer, Module, Reference, Scope, Space, Symbol } from 'yuku-analyzer';
3	import { anchorSite, anchorSymbol, resolveSymbolAnchor } from './anchors.ts';
4	import {
5		makeReceipt,
6		type QueryRequest,
7		type Receipt,
8		type SymbolAnchor,
9		type UnresolvedSite,
10	} from './contracts.ts';
11	import { analyzerSnapshot } from './snapshot.ts';
12	
13	export interface ReferenceResult {
14		readonly site: SymbolAnchor;
15		readonly access: 'read' | 'write' | 'read-write';
16	}
17	export interface CaptureResult {
18		readonly symbol: SymbolAnchor;
19		readonly references: readonly SymbolAnchor[];
20		readonly isWritten: boolean;
21	}
22	export interface ExportResult {
23		readonly name: string;
24		readonly module: SymbolAnchor;
25	}
26	
27	const nodeBuiltins = new Set([...builtinModules, ...builtinModules.map((name) => `node:${name}`)]);
28	type YukuNode = Parameters<Module['symbolOf']>[0];
29	type RichNode = YukuNode & {
30		type: string;
31		operator?: string;
32		left?: YukuNode;
33		right?: YukuNode;
34		object?: YukuNode;
35		property?: YukuNode;
36		computed?: boolean;
37		value?: unknown;
38		id?: YukuNode;
39		init?: YukuNode;
40		expression?: YukuNode;
41		expressions?: YukuNode[];
42		argument?: YukuNode;
43		arguments?: YukuNode[];
44		consequent?: YukuNode;
45		alternate?: YukuNode;
46		key?: YukuNode;
47		name?: string;
48		properties?: YukuNode[];
49		elements?: Array<YukuNode | null>;
50		quasi?: YukuNode;
51	};
52	
53	const transparentExpressions = new Set([
54		'ParenthesizedExpression',
55		'TSAsExpression',
56		'TSTypeAssertion',
57		'TSSatisfiesExpression',
58		'TSNonNullExpression',
59	]);
60	
61	function expressionAccess(
62		module: Module,
63		node: YukuNode,
64		fallback: ReferenceResult['access'] = 'read',
65	): ReferenceResult['access'] {
66		let current: YukuNode = node;
67		while (true) {
68			const parent = module.parentOf(current) as RichNode | null;
69			if (parent === null) return fallback;
70			if (parent.type === 'UpdateExpression') return 'read-write';
71			if (parent.type === 'UnaryExpression' && parent.operator === 'delete') return 'write';
72			if (
73				parent.type === 'AssignmentExpression' &&
74				parent.left !== undefined &&
75				isWithin(module, node, parent.left)
76			)
77				return parent.operator === '=' ? 'write' : 'read-write';
78			if (
79				(parent.type === 'ForInStatement' || parent.type === 'ForOfStatement') &&
80				parent.left !== undefined &&
81				isWithin(module, node, parent.left)
82			)
83				return 'write';
84			if (
85				[
86					'ExpressionStatement',
87					'ReturnStatement',
88					'CallExpression',
89					'FunctionDeclaration',
90					'FunctionExpression',
91					'ArrowFunctionExpression',
92					'Program',
93				].includes(parent.type)
94			)
95				return fallback;
96			current = parent;
97		}
98	}
99	
100	function referenceAccess(reference: Reference): ReferenceResult['access'] {
101		return reference.isWrite ? expressionAccess(reference.module, reference.node, 'write') : 'read';
102	}
103	
104	function uniqueUnresolved(items: UnresolvedSite[]): UnresolvedSite[] {
105		const seen = new Set<string>();
106		return items
107			.filter((item) => {
108				const key = `${item.reason}:${item.site.file}:${item.site.semanticPath.join('\u0000')}:${item.site.fingerprint}`;
109				if (seen.has(key)) return false;
110				seen.add(key);
111				return true;
112			})
113			.sort((a, b) =>
114				`${a.site.file}:${a.site.semanticPath.join('/')}:${a.reason}`.localeCompare(
115					`${b.site.file}:${b.site.semanticPath.join('/')}:${b.reason}`,
116				),
117			);
118	}
119	
120	function moduleClosure(seed: Module, direction: 'dependencies' | 'dependents'): Set<Module> {
121		const modules = new Set<Module>([seed]);
122		const queue = [seed];
123		for (const module of queue)
124			for (const next of module[direction])
125				if (!modules.has(next)) {
126					modules.add(next);
127					queue.push(next);
128				}
129		return modules;
130	}
131	
132	function baseUnresolved(analyzer: Analyzer, relevant: ReadonlySet<Module>): UnresolvedSite[] {
133		const unresolved: UnresolvedSite[] = [];
134		for (const module of analyzer.modules.values()) {
135			if (!relevant.has(module)) continue;
136			for (const [index, diagnostic] of module.diagnostics.entries())
137				unresolved.push({
138					site: anchorSite(module, undefined, 'parse-diagnostic', index),
139					reason: 'unparsed-file',
140					detail: diagnostic.message,
141				});
142			for (const record of module.imports) {
143				if (record.resolvedModule !== null) continue;
144				const reason = moduleBoundaryReason(record.specifier);
145				unresolved.push({
146					site: anchorSite(module, record.node, 'import-boundary'),
147					reason,
148					detail: `Import '${record.specifier}' leaves the linked file set.`,
149				});
150			}
151			for (const record of module.exports) {
152				if (record.specifier === null || record.resolvedModule !== null) continue;
153				const reason = moduleBoundaryReason(record.specifier);
154				unresolved.push({
155					site: anchorSite(module, record.node, 'export-boundary'),
156					reason,
157					detail: `Export from '${record.specifier}' leaves the linked file set.`,
158				});
159			}
160		}
161		for (const [index, diagnostic] of analyzer.diagnostics.entries()) {
162			const module = analyzer.module(diagnostic.module);
163			if (module === undefined || !relevant.has(module)) continue;
164			unresolved.push({
165				site: anchorSite(module, undefined, 'link-diagnostic', index),
166				reason: diagnostic.message.includes('ambiguous')
167					? 'ambiguous-definition'
168					: 'unresolved-symbol',
169				detail: diagnostic.message,
170			});
171		}
172		return unresolved;
173	}
174	
175	function moduleBoundaryReason(
176		specifier: string,
177	): 'builtin-module-boundary' | 'external-module-boundary' | 'unresolved-specifier' {
178		return nodeBuiltins.has(specifier)
179			? 'builtin-module-boundary'
180			: specifier.startsWith('.')
181				? 'unresolved-specifier'
182				: 'external-module-boundary';
183	}
184	
185	function namespaceEvidence(
186		analyzer: Analyzer,
187		origin: Symbol,
188	): { results: ReferenceResult[]; unresolved: UnresolvedSite[] } {
189		const results: ReferenceResult[] = [];
190		const unresolved: UnresolvedSite[] = [];
191		for (const module of analyzer.modules.values())
192			for (const record of module.imports) {
193				if (!record.isNamespace || record.local === null || record.resolvedModule === null)
194					continue;
195				for (const reference of record.local.references) {
196					const member = module.parentOf(reference.node) as RichNode | null;
197					if (member?.type !== 'MemberExpression' || member.object !== reference.node)
198						continue;
199					const property = member.property as RichNode;
200					const key = staticMemberKey(member);
201					if (key !== null) {
202						const routes = resolvedSymbolPaths(
203							analyzer,
204							record.resolvedModule,
205							String(key),
206							origin,
207						);
208						for (const route of routes) {
209							let current = member;
210							let remaining = route;
211							while (remaining.length > 0) {
212								const parent = module.parentOf(current) as RichNode | null;
213								if (parent?.type !== 'MemberExpression' || parent.object !== current)
214									break;
215								const nextKey = staticMemberKey(parent);
216								if (nextKey === null || nextKey !== remaining[0]) break;
217								current = parent;
218								remaining = remaining.slice(1);
219							}
220							if (remaining.length > 0) continue;
221							const finalProperty = (current as RichNode).property as
222								| YukuNode
223								| undefined;
224							results.push({
225								site: anchorSite(module, finalProperty ?? property, 'namespace-member'),
226								access: expressionAccess(module, current),
227							});
228						}
229						if (routes.length > 0) continue;
230					}
231					if (
232						key !== null ||
233						exportedSymbolPaths(analyzer, record.resolvedModule, origin).length === 0
234					)
235						continue;
236					const reason =
237						property.type === 'Literal' && typeof property.value === 'string'
238							? 'string-keyed-lookup'
239							: property.type === 'Identifier'
240								? 'dynamic-member-access'
241								: 'computed-property-key';
242					unresolved.push({
243						site: anchorSite(module, member, 'computed-member'),
244						reason,
245						detail: `Computed member may name '${origin.name}', but binding evidence cannot prove it.`,
246					});
247				}
248			}
249		return { results, unresolved };
250	}
251	
252	type FlowSegment = string | number | '*';
