261	function resolvedSymbolPaths(
262		analyzer: Analyzer,
263		module: Module,
264		name: string,
265		symbol: Symbol,
266		seen = new Set<string>(),
267	): FlowPath[] {
268		const seenKey = `${module.path}:${name}:${symbol.module.path}:${symbol.id}`;
269		if (seen.has(seenKey)) return [];
270		seen.add(seenKey);
271		const paths: FlowPath[] = [];
272		const direct = module.exports.filter((record) => record.name === name);
273		for (const record of direct) {
274			if (record.local !== null) {
275				const definition = analyzer.definitionOf(record.local)?.symbol;
276				if (record.local === symbol || definition === symbol) paths.push([]);
277				else {
278					const imported = module.imports.find(
279						(candidate) => candidate.local === record.local,
280					);
281					if (
282						imported !== undefined &&
283						imported.resolvedModule !== null &&
284						imported.name !== null
285					)
286						paths.push(
287							...resolvedSymbolPaths(
288								analyzer,
289								imported.resolvedModule,
290								imported.name,
291								symbol,
292								seen,
293							),
294						);
295				}
296			} else if (record.isNamespaceReexport && record.resolvedModule !== null)
297				for (const exportedName of record.resolvedModule.exportedNames())
298					paths.push(
299						...resolvedSymbolPaths(
300							analyzer,
301							record.resolvedModule,
302							exportedName,
303							symbol,
304							seen,
305						).map((path) => [exportedName, ...path]),
306					);
307			else if (record.resolvedModule !== null && record.fromName !== null)
308				paths.push(
309					...resolvedSymbolPaths(
310						analyzer,
311						record.resolvedModule,
312						record.fromName,
313						symbol,
314						seen,
315					),
316				);
317		}
318		if (direct.length === 0 && name !== 'default')
319			for (const record of module.exports)
320				if (record.isStar && record.resolvedModule !== null)
321					paths.push(
322						...resolvedSymbolPaths(analyzer, record.resolvedModule, name, symbol, seen),
323					);
324		return uniquePaths(paths);
325	}
