337	function transportedImportEvidence(analyzer: Analyzer, origin: Symbol): ReferenceResult[] {
338		const results: ReferenceResult[] = [];
339		const cited = new Set<YukuNode>();
340		for (const module of analyzer.modules.values())
341			for (const imported of module.imports) {
342				if (
343					imported.isNamespace ||
344					imported.local === null ||
345					imported.name === null ||
346					imported.resolvedModule === null
347				)
348					continue;
349				const routes = resolvedSymbolPaths(
350					analyzer,
351					imported.resolvedModule,
352					imported.name,
353					origin,
354				).filter((path) => path.length > 0);
355				for (const reference of imported.local.references)
356					for (const route of routes) {
357						let current: YukuNode = reference.node;
358						let remaining = route;
359						while (remaining.length > 0) {
360							const parent = module.parentOf(current) as RichNode | null;
361							if (parent?.type !== 'MemberExpression' || parent.object !== current) break;
362							const key = staticMemberKey(parent);
363							if (key === null || key !== remaining[0]) break;
364							current = parent;
365							remaining = remaining.slice(1);
366						}
367						if (remaining.length > 0 || cited.has(current)) continue;
368						cited.add(current);
369						const property = (current as RichNode).property as YukuNode | undefined;
370						results.push({
371							site: anchorSite(module, property ?? current, 'namespace-export-member'),
372							access: expressionAccess(module, current),
373						});
