386		if (seen.has(seenKey)) return [];
387		seen.add(seenKey);
388		const paths: FlowPath[] = [];
389		const direct = module.exports.filter((record) => record.name === name);
390		for (const record of direct) {
391			if (record.local !== null) {
392				const imported = module.imports.find((candidate) => candidate.local === record.local);
393				if (
394					imported?.resolvedModule !== null &&
395					imported?.resolvedModule !== undefined &&
396					imported.name !== null
