407							exportedName,
408							target,
409							seen,
410						).map((path) => [exportedName, ...path]),
411					);
412			else if (record.resolvedModule !== null && record.fromName !== null)
413				paths.push(
414					...resolvedAnonymousPaths(record.resolvedModule, record.fromName, target, seen),
415				);
416		}
417		if (direct.length === 0 && name !== 'default')
418			for (const record of module.exports)
419				if (record.isStar && record.resolvedModule !== null)
420					paths.push(...resolvedAnonymousPaths(record.resolvedModule, name, target, seen));
