424	function queueAnonymousDefaultImports(
425		analyzer: Analyzer,
426		module: Module,
427		exportNode: YukuNode,
428		paths: readonly FlowPath[],
429		queue: AliasFlow[],
430	): void {
431		const exported = module.exports.find(
432			(record) =>
433				record.name === 'default' && record.specifier === null && record.node === exportNode,
434		);
435		if (exported === undefined) return;
436		for (const dependent of analyzer.modules.values())
437			for (const imported of dependent.imports) {
438				if (imported.local === null || imported.resolvedModule === null) continue;
439				const routes = imported.isNamespace
440					? imported.resolvedModule
441							.exportedNames()
442							.flatMap((name) =>
443								resolvedAnonymousPaths(imported.resolvedModule!, name, exported).map(
444									(path) => [name, ...path],
445								),
446							)
447					: imported.name === null
448						? []
449						: resolvedAnonymousPaths(imported.resolvedModule, imported.name, exported);
450				if (routes.length > 0)
451					queue.push({ symbol: imported.local, paths: concatPaths(routes, paths) });
452			}
453	}
