455	function queueSymbolImports(analyzer: Analyzer, item: AliasFlow, queue: AliasFlow[]): void {
456		for (const module of analyzer.modules.values())
457			for (const imported of module.imports) {
458				if (imported.local === null || imported.resolvedModule === null) continue;
459				const routes = imported.isNamespace
460					? exportedSymbolPaths(analyzer, imported.resolvedModule, item.symbol)
461					: imported.name === null
462						? []
463						: resolvedSymbolPaths(
464								analyzer,
465								imported.resolvedModule,
466								imported.name,
467								item.symbol,
468							);
469				const transported = routes.filter((path) =>
470					imported.isNamespace ? path.length > 1 : path.length > 0,
471				);
472				if (transported.length > 0)
473					queue.push({
474						symbol: imported.local,
475						paths: concatPaths(transported, item.paths),
476					});
477			}
478	}
