480	function propertyAliasGaps(analyzer: Analyzer, origin: Symbol): UnresolvedSite[] {
481		const unresolved: UnresolvedSite[] = [];
482		const queue: AliasFlow[] = [{ symbol: origin, paths: [[]] }];
483		const seen = new Set<string>();
484		for (const item of queue) {
485			const paths = uniquePaths(item.paths);
486			const key = `${item.symbol.module.path}:${item.symbol.id}:${JSON.stringify(paths)}`;
