669						current = parent;
670						currentPaths = [[]];
671						continue;
672					}
673					if (
674						parent.type === 'TemplateLiteral' &&
675						parent.expressions?.includes(current) &&
676						(module.parentOf(parent) as RichNode | null)?.type ===
