706	function memberIsMutated(module: Module, member: YukuNode): boolean {
707		let current = member;
708		let parent = module.parentOf(current) as RichNode | null;
709		while (parent?.type === 'ChainExpression' && parent.expression === current) {
710			current = parent;
711			parent = module.parentOf(current) as RichNode | null;
712		}
713		if (parent?.type === 'MemberExpression' && parent.object === current) return false;
714		return expressionAccess(module, member) !== 'read';
