778			return;
779		}
780		if (node.type === 'AssignmentPattern' && node.left !== undefined) {
781			queuePatternBindings(module, node.left, paths, queue, unresolved, origin);
782			return;
783		}
784		if (node.type === 'RestElement' && node.argument !== undefined) {
