805					if (key !== null)
806						queuePatternBindings(
807							module,
808							property.value as YukuNode,
809							pathsAtKey(paths, key),
810							queue,
811							unresolved,
812							origin,
813						);
814					else if (paths.length > 0)
815						unresolved.push({
816							site: anchorSite(module, property, 'aggregate-dynamic-extraction'),
817							reason: 'property-alias-write-uncertain',
818							detail: `Dynamic aggregate extraction may select '${origin.name}'.`,
819						});
820				} else if (property.type === 'RestElement' && property.argument !== undefined)
