857	function uniquePaths(paths: readonly FlowPath[]): FlowPath[] {
858		const seen = new Set<string>();
859		return paths.filter((path) => {
860			const key = JSON.stringify(path);
861			if (seen.has(key)) return false;
862			seen.add(key);
863			return true;
864		});
865	}
