867	function finish<T>(
868		analyzer: Analyzer,
869		request: QueryRequest,
870		results: T[],
871		unresolved: UnresolvedSite[],
872	): Receipt<T> {
873		const sorted = [...results].sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)));
874		const gaps = uniqueUnresolved(unresolved);
875		const snapshot = analyzerSnapshot(analyzer);
876		const query = request.kind;
877		return gaps.length === 0
878			? makeReceipt({
879					schema: 'guessless.receipt/v1',
880					state: 'complete',
881					query,
882					request,
883					snapshot,
884					results: sorted,
885				})
886			: makeReceipt({
887					schema: 'guessless.receipt/v1',
888					state: 'partial',
889					query,
890					request,
891					snapshot,
892					results: sorted,
893					unresolved: gaps,
894				});
895	}
