917		request: QueryRequest,
918		anchor: SymbolAnchor,
919	): Symbol | Receipt<never> {
920		return (
921			resolveSymbolAnchor(analyzer.modules, anchor) ??
922			refuse(
923				analyzer,
924				request,
925				'unresolved-symbol',
926				'The anchor is missing, changed, deleted, or ambiguous; resolution fails closed.',
927			)
928		);
929	}
930	
931	export function definitionOf(analyzer: Analyzer, anchor: SymbolAnchor): Receipt<SymbolAnchor> {
932		const request = { kind: 'definitionOf', target: anchor } as const;
933		const symbol = resolveOrRefuse(analyzer, request, anchor);
934		if (!('module' in symbol)) return symbol;
935		const definition = analyzer.definitionOf(symbol);
936		const relevant = moduleClosure(symbol.module, 'dependencies');
937		if (definition?.symbol === null || definition === null)
938			return finish(
939				analyzer,
940				request,
941				[],
942				[
943					...baseUnresolved(analyzer, relevant),
944					{
945						site: anchor,
946						reason: 'unresolved-symbol',
947						detail: 'Yuku could not prove one defining symbol.',
948					},
949				],
950			);
951		return finish(
952			analyzer,
953			request,
954			[anchorSymbol(definition.symbol)],
955			baseUnresolved(analyzer, relevant),
956		);
957	}
958	
959	export function referencesOf(
960		analyzer: Analyzer,
961		anchor: SymbolAnchor,
962		mode: 'all' | 'reads' | 'writes' = 'all',
963	): Receipt<ReferenceResult> {
964		const query = mode === 'all' ? 'referencesOf' : mode === 'reads' ? 'readsOf' : 'writesOf';
965		const request = { kind: query, target: anchor } as const;
966		const symbol = resolveOrRefuse(analyzer, request, anchor);
967		if (!('module' in symbol)) return symbol;
968		const origin = analyzer.definitionOf(symbol)?.symbol ?? symbol;
969		const results = analyzer.referencesOf(origin).map(({ module, reference }) => ({
970			site: anchorSite(module, reference.node, 'reference'),
971			access: referenceAccess(reference),
972		}));
973		const namespace = namespaceEvidence(analyzer, origin);
974		results.push(...namespace.results);
975		results.push(...transportedImportEvidence(analyzer, origin));
976		const filtered = results.filter(
977			(result) =>
978				mode === 'all' ||
979				(mode === 'reads' ? result.access !== 'write' : result.access !== 'read'),
980		);
981		const relevant = moduleClosure(origin.module, 'dependents');
982		return finish(analyzer, request, filtered, [
983			...baseUnresolved(analyzer, relevant),
984			...namespace.unresolved,
985			...propertyAliasGaps(analyzer, origin),
986		]);
987	}
988	
989	export function exportedNames(module: Module): Receipt<ExportResult> {
990		const relevant = moduleClosure(module, 'dependencies');
991		return finish(
992			module.analyzer,
993			{ kind: 'exportedNames', file: module.path },
994			module
995				.exportedNames()
996				.map((name) => ({ name, module: anchorSite(module, undefined, 'exports') })),
997			baseUnresolved(module.analyzer, relevant),
998		);
999	}
1000	
1001	function functionNode(symbol: Symbol): YukuNode | undefined {
1002		for (const declaration of symbol.declarations) {
1003			const parent = symbol.module.parentOf(declaration) as RichNode | null;
1004			if (parent !== null && ['FunctionDeclaration', 'FunctionExpression'].includes(parent.type))
1005				return parent;
1006			if (
1007				parent?.type === 'VariableDeclarator' &&
1008				parent.init !== undefined &&
1009				['FunctionExpression', 'ArrowFunctionExpression'].includes(parent.init.type)
1010			)
1011				return parent.init;
1012		}
1013		return undefined;
1014	}
1015	
1016	function isWithin(module: Module, child: YukuNode, ancestor: YukuNode): boolean {
1017		let current: YukuNode | null = child;
1018		while (current !== null) {
1019			if (current === ancestor) return true;
1020			current = module.parentOf(current);
1021		}
1022		return false;
1023	}
1024	
1025	export function capturesOf(analyzer: Analyzer, anchor: SymbolAnchor): Receipt<CaptureResult> {
1026		const request = { kind: 'capturesOf', target: anchor } as const;
1027		const symbol = resolveOrRefuse(analyzer, request, anchor);
1028		if (!('module' in symbol)) return symbol;
1029		const node = functionNode(symbol);
1030		if (node === undefined)
1031			return refuse(
1032				analyzer,
1033				request,
1034				'unsupported-syntax',
1035				'The anchored symbol is not backed by a function node.',
1036			);
1037		const results = symbol.module.capturesOf(node).map((capture) => ({
1038			symbol: anchorSymbol(capture.symbol),
1039			references: capture.references.map((reference) =>
1040				anchorSite(symbol.module, reference.node, 'capture-reference'),
1041			),
1042			isWritten: capture.isWritten,
1043		}));
1044		const unresolved = baseUnresolved(analyzer, new Set([symbol.module]));
1045		for (const reference of symbol.module.unresolvedReferences)
1046			if (isWithin(symbol.module, reference.node, node))
1047				unresolved.push({
1048					site: anchorSite(symbol.module, reference.node, 'unresolved-capture'),
1049					reason: 'unresolved-symbol',
1050					detail: `Unresolved/global '${reference.name}' is a capture boundary.`,
1051				});
1052		return finish(analyzer, request, results, unresolved);
1053	}
1054	
1055	export function resolveBinding(
1056		analyzer: Analyzer,
1057		module: Module,
1058		name: string,
1059		space: Space = 'value',
1060		from?: Scope,
1061		scopeAnchor: SymbolAnchor | null = null,
1062	): Receipt<SymbolAnchor> {
1063		const request = {
1064			kind: 'resolveBinding',
1065			file: module.path,
1066			name,
1067			space,
1068			scope: scopeAnchor,
1069		} as const;
1070		const symbol = module.resolve(name, from, space);
1071		if (symbol !== null && symbol.module !== module)
1072			return refuse(
1073				analyzer,
1074				request,
1075				'unresolved-symbol',
1076				'The resolved binding belongs to a different module; resolution fails closed.',
1077			);
1078		return finish(
1079			analyzer,
1080			request,
1081			symbol === null ? [] : [anchorSymbol(symbol)],
1082			baseUnresolved(analyzer, new Set([module])),
1083		);
1084	}
